  "suburb": { m: "sub- (dưới, gần) + urb (thành phố, như urban) → vùng sát thành phố → ngoại ô.", e: "Sai: live in suburb → Đúng: live in the suburbs. Dạng tính từ: suburban (adj).", u: "Part 4, 7 bất động sản: a quiet suburb, commute from the suburbs, open a branch in the suburbs.", f: "suburb (n), suburbs (n), suburban (adj), suburbia (n)" },
  "takeover": { m: "take (lấy) + over (hẳn, sang) → lấy hẳn quyền kiểm soát công ty khác → thâu tóm.", e: "Danh từ viết liền: a takeover. Động từ tách rời: Sai: takeover the company → Đúng: take over the company.", u: "Part 7 tin kinh doanh: a takeover bid, hostile takeover, after the takeover of Brex Inc.", f: "take over (v), takeover (n), acquisition (n), merger (n)" },
